window.harnessChunks["rows-0ad77166d24d74b7.js"]=["<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/FoundationAgents/OpenManus\" target=\"_blank\" rel=\"noopener\">OpenManus</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/FoundationAgents/OpenManus/tree/3309bf4e416fb1c74b008f3e86494439a31bad53\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3309bf4e416fb1c74b008f3e86494439a31bad53\">3309bf4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: configured agents autonomously execute task steps with tools/model reasoning under the planning flow.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: sequencing and assignment of planned steps do not establish a dedicated interference-regulation mechanism among multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: plan status and agent dispatch manage the current workflow, but no whole-system current-control authority over shared organizational resources/commitments was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: plan/status checks are part of normal execution; no independent complementary audit channel with distinct access was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: the planner reasons about how to accomplish the present task. Under the profile, internal task planning is not S4 without prospective external-environment intelligence that changes system capability/strategy.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: mission, prompts, agents and policies are externally configured; no autonomous ultimate identity/value authority is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/openmanus.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/langchain-ai/langgraph-bigtool\" target=\"_blank\" rel=\"noopener\">LangGraph BigTool</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/langchain-ai/langgraph-bigtool/tree/0bb7f9227d349afa4d4207c6630e800658c80894\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0bb7f9227d349afa4d4207c6630e800658c80894\">0bb7f92 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the graph supports an autonomous agent that selects and executes tools iteratively against task feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: graph transitions and tool retrieval coordinate steps inside one operational process; no regulation of interference among multiple autonomous S1 units was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: registry/retrieval state and graph routing do not constitute whole-system current authority over resources/commitments across S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit function distinct from the normal agent/tool execution graph was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: tool retrieval adapts the immediate capability surface to the current task but does not scan an external future environment or adapt the organization over a prospective horizon.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: the registry, graph, prompts and tool policies are application-defined; no autonomous ultimate policy/identity function is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/langgraph-bigtool.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-30T20:32:34+03:00\"><th scope=\"row\"><a href=\"https://github.com/agentarea/agentarea\" target=\"_blank\" rel=\"noopener\">AgentArea</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-30\">2026-10-30</time></td><td class=\"review-ref\"><a href=\"https://github.com/agentarea/agentarea/tree/6e610c4ffffdf6b6ba8e45cba27b3ba577e8476c\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6e610c4ffffdf6b6ba8e45cba27b3ba577e8476c\">6e610c4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: configured model agent carries out a task with independent choice of reasoning, completion and permitted tool actions. - Disturbance / variety regulated: new instructions, tool outputs, external APIs, model feedback, errors, budget limits, user follow-up. - Decisive decision or feedback right: choose subsequent task step, issue tool calls, delegate where allowed and decide to complete. - Decision owner: model-backed agent acting inside the first-party workflow; Temporal controls state transitions but does not select the model&#39;s task judgment. - Supporting / enforcement mechanisms: Temporal durable workflow, model activity, policy gate, MCP tool execution, budget tracker and task/event database. - Closure path: workspace task → model response → tool/delegation results appended to context → next model turn / completion event to user. - Boundary reachability: the shipped AgentExecutionWorkflow.run and its tool/LLM loop are used by the first-party worker, not merely defined in a test fixture. - Why this is / is not agent-owned: the autonomous actor chooses task actions within the configured bounds, whereas deterministic ceilings and workflow persistence only constrain that autonomy. - Evidence: execution workflow, Temporal runner, README runtime. - Basis: shipped first-party execution path, not marketing text alone. - Confidence: high for configured model-backed tasks. - Caveats: model inference and MCP servers are external and must be installed/configured; no live work was invoked during assessment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no first-party S2 regulation path sufficiently evidenced for specific interference among distinct S1 task cells at the declared workspace recursion. - Disturbance / variety regulated: concurrent delegated agents could duplicate work, contend for an external resource or diverge, but a potential conflict is not evidence of an attenuating S2 loop. - Decisive decision or feedback right: no specific cross-S1 oscillation/commitment arbitration decision and returned correction established in the reviewed standard execution path. - Decision owner: not established. - Supporting / enforcement mechanisms: parallel child workflow fan-out, inbox, agent discovery, workspace scoping, role permissions and network topology; these transport or constrain interactions without proving S2 on their own. - Closure path: task delegations and result collection exist; no demonstrated conflict-specific adjustment returned to two competing S1 cells. - Why this is / is not agent-owned: an agent can choose which worker to delegate to, but decomposition, shared communication and access control alone do not constitute S2-specific stabilization. - Evidence: concurrent delegated calls in workflow, read-only topology tool, agentic networks docs. - Basis: Methodology-specific negative calibration, not a claim that multi-agent use is impossible. - Confidence: moderate. - Caveats: deployment-specific worker conventions may regulate collisions, but are not established by the shipped paths reviewed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C(P) - Function: workspace-wide current regulation of permitted agent execution, shared tool rights, task budgets and resource commitments. - Disturbance / variety regulated: excessive model/tool spend, unauthorized actions and incompatible active run permissions across the workspace. - Whole-system current view: the workspace-scoped policy registry, policy rule listing, effective resolution for agents/tasks and live task status/budget counters. - Current-control decision scope: set/revise workspace policy rules, permitted tools, run budget and escalation requirements that constrain multiple S1 tasks. - Decisive decision or feedback right: choose policy rules and current resource allowances; authorize/reject sensitive work and changes. - Decision owner: in the standard parent mode, an authorized workspace human/operator; in the constructor mode, a separately composed and granted agent could choose mutations through the shipped privileged PoliciesToolset, but the reviewed distribution does not ship a completed autonomous management policy. - Supporting / enforcement mechanisms: governance API, effective-policy resolver, assertenforceable, decidetoolaction, task snapshot, budget tracker, REST/MCP authorization and Temporal continuation machinery. - Closure path: parent changes rules → policy is persisted/resolved into the next task or authorized policy revision → gate denies/approves requests or budget enforces the new rule. The constructor surface lists and writes rules via the same service, but needs externally composed agent decision and appropriate authority. - Boundary reachability: the first-party getplatformtools() registers PoliciesToolset, and its privileged create/update calls the live workspace governance service; the run workflow consumes enforceable policies. Parent API is likewise a shipped operating route. - Why this is / is not agent-owned: the only complete current-control governance mode observed is parent-owned; the shipped S3-specific toolset is a reachable constructor that can be given to an agent, not itself agent discretion. Therefore C(P), not A(P). - Evidence: policies toolset, platform tool registration, governance policy API, workflow policy gate and revisions. - Basis: two distinct reachable ownership modes with actual policy application. - Confidence: moderate; optional privileged agent toolsets require explicit authority. - Caveats: a single-task budget tracker alone is not whole-workspace S3; the cross-task policy registry/rule resolution is the relevant whole-system control scope.\">C(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independent complementary probe of an agent&#39;s routine execution reports is established as an organizational audit path. - Disturbance / variety regulated: model-tool reports might omit actual outcomes; complementary evidence would require independent access and return. - Decisive decision or feedback right: no separate audit authority with a corrective verdict loop identified. - Decision owner: none established. - Supporting / enforcement mechanisms: task events, audit logs, AuditToolset, policy observer and artifact validation of own outputs; these are compliance/ordinary operational checks unless independently controlled. - Closure path: no evidence of an independent auditor inspecting reality outside the ordinary workflow and returning findings to workspace control. - Why this is / is not agent-owned: a tool named audit and recorded execution events are not a separate autonomous audit judge. - Evidence: audit toolset registration, audit observer, artifact validation. - Basis: absence in reviewed deployed operating boundary. - Confidence: moderate. - Caveats: external evaluators or project-specific independent audit agents can be built with the platform; not credited without a wired first-party mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no standard workspace-level externally prospective intelligence and adaptation-option loop established. - Disturbance / variety regulated: provider/model capability changes, new security threats, user requirements and future tool opportunities are environmental variety. - Decisive decision or feedback right: no first-party loop selecting and returning future-oriented capability adaptation to workspace policy/current control. - Decision owner: none established for the scoped S4 function. - Supporting / enforcement mechanisms: registry/provider discovery, model/tool catalogs, event triggers and user-supplied research-agent tasks. - Closure path: new registry/provider data may be browsed or synced, but is not a model of alternative future adaptation options returned to S3. - Why this is / is not agent-owned: a research agent pursuing a user task is S1, not automatically the workspace&#39;s strategic intelligence. - Evidence: registry service, provider model discovery, README. - Basis: negative-state scoped to shipped workspace runtime rather than user-installed future planners. - Confidence: moderate. - Caveats: the repository contains roadmaps and examples of prospective work, excluded as adjacent development/governance.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: parent ownership of workspace identity, legitimate actor permissions and ultimate governance policy for allowed agent activity. - Disturbance / variety regulated: conflicting user/agent claims to authority, workspace risk posture, policy boundaries and rules governing future tasks. - Identity / ultimate-policy issue: who belongs to the workspace and can change its governing baseline, and which categories of agent tool/work are legitimate. - Ultimate authority in each claimed mode: workspace administrator/human/legitimate parent through workspace and governance-policy APIs, with a first-party authorization graph. A privileged tool&#39;s existence is not proof that an agent owns ultimate workspace identity. - Return-to-operation path: parent establishes/updates baseline rules and membership → persistent workspace-scoped governance service/authorization → effective policy snapshot and tool/approval gate regulate subsequent tasks and tools. - Decisive decision or feedback right: ultimate workspace operating/identity/risk boundary decisions, distinct from approving one routine tool call. - Decision owner: authorized parent workspace authority; model agents act within, not above, the policy they are given. - Supporting / enforcement mechanisms: workspace baseline seeding, permission graph, governance policy resolver, effective task policy, human approval and identity context. - Closure path: workspace policy decision → saved enforceable rules → new or revised task policy → subsequent tool/action allowed, denied, or escalated under that authority. - Boundary reachability: the first-party workspace creation API seeds a policy baseline; the same workspace rule service and workflow policy consumer operate in the shipped API/worker mode. - Why this is / is not agent-owned: runtime restrictions and prompts are supports. Parent governance is credited only because authenticated change and later-task enforcement close a concrete workspace identity/authority loop. - Evidence: workspace creation route, governance policy API, policy resolver, workflow gate. - Basis: parent authority, workspace identity policy and durable return. - Confidence: moderate. - Caveats: per-tool approval alone belongs to current operational control; it is not used as standalone S5 evidence.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/191e3ad8114297a7267a278185c8e246537fb98e/assessments/ag/agentarea.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 191e3ad8114297a7267a278185c8e246537fb98e\">191e3ad &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-10T16:09:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/Team-Commonly/commonly\" target=\"_blank\" rel=\"noopener\">Commonly</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-10\">2026-10-10</time></td><td class=\"review-ref\"><a href=\"https://github.com/Team-Commonly/commonly/tree/669889886a9436b8349e4e60e5197bab504909e8\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 669889886a9436b8349e4e60e5197bab504909e8\">6698898 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: run real model/tool/feedback sessions for installed native agents serving pod requests and updating pod messages/tasks/memory. - Disturbance / variety regulated: pod user requests, changing discussion context, returned tool outcomes, memory and local service errors. - Decisive decision or feedback right: which reply and allowed tool call to make in each native model turn, and whether to continue with additional tools. - Decision owner: the installed native agent&#39;s model-backed turn; Commonly supplies the actual bounded model-call/tool-result loop. - Supporting / enforcement mechanisms: runAgent, LiteLLM /chat/completions, allowlisted commonly tool dispatcher, AgentRun traces, message/claim constraints and caps. - Closure path: an addressed/scheduled native installation receives trigger → model chooses tool call → first-party dispatcher executes permitted tool → result enters message history → next model turn chooses subsequent action/response. - Boundary reachability: shipped native runtimeType:&#39;native&#39; installations are dispatched through first-party agentEventService to nativeRuntimeService when LiteLLM is configured; optional BYO seats are not needed to demonstrate the native loop. - Why this is / is not agent-owned: removing model calls leaves relay/DB handlers and deterministic tools but no discretionary content/operation decisions. - Evidence: nativeRuntimeService.ts; agentEventService.ts; task-clerk.ts; index.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: Native LiteLLM must be configured; BYO seats alone are not a first-party native model loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate duplicate or abandoned work by two distinct active seat agents receiving the same human pod message through first-party exclusive attention claims and bounded handoff. - Disturbance / variety regulated: multiple seat S1s may answer the same broad human message, produce duplicate/conflicting replies, or a dead/declining seat may leave it unattended. - Decisive decision or feedback right: determine which seat may own a message claim, make other seats stand down and select the next eligible wake target after an explicit decline. - Decision owner: first-party deterministic CAS lease/attention kernel plus preconfigured original wake-target set, not a packaged autonomous coordinator that adaptively decides agent selection. - Supporting / enforcement mechanisms: messageclaims transaction/lease with a single valid holder, decline history, handoff service and per-seat runtime claim/release paths. - Closure path: broadcast message produces potential seat wakeups → claim transaction grants one seat/denies other → loser stands down → winner processes, or explicitly declines → release/handoff enqueues next eligible original seat → next S1 acts while rejected seats do not. - Boundary reachability: native runtime attempts claims before model work and releases them at terminal; shipped local/CLI adapters also use the shared kernel, though their own external cognition is not credited to the kernel. - Why this is / is not agent-owned: the disturbance-specific first-party gate and returned handoff are real, but their selection policy is enforced by lease/CAS and configured targets, not autonomously chosen by a first-party S2 model actor; this is C, not A. - Evidence: messageClaimService.ts; messageClaimHandoffService.ts; nativeRuntimeService.ts; agentMentionService.ts. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: A deterministic exclusive claim is a real S2-specific construction path, not agent-owned planning; seat-agent cognition and policy choice are not credited to the kernel.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: a legitimate human pod-member/operator sees the pod task portfolio and installed agents and can revise current assignments, statuses and commitments, returning those revisions to active work. - Disturbance / variety regulated: misallocated, stale or blocked pod tasks and changes to commitments/work priorities across seats. - Decisive decision or feedback right: human pod member with write authority can assign/reassign, change task status, dependency and scope, and push the new current commitments into agent notifications. - Decision owner: authorized human pod operator/member in the supported parent-governed task-board mode; not the native model or automated lease/scheduler. - Supporting / enforcement mechanisms: pod-scoped GET of full task set with lease states, PATCH task fields, membership write check, per-task update history, task event notifications, UI board. - Closure path: operator observes complete pod task board plus seat status → makes current-work allocation/status decision → authorized task PATCH commits changed assignment/status → notifyPodAgents and board events deliver feedback to operational seat agents. - Boundary reachability: the self-hosted web UI and backend task APIs ship as the supported human-in-the-loop pod control mode; all task changes are scoped to a pod and gated to writers. - Why this is / is not agent-owned: the model/tool loops and message claims do not autonomously aggregate and control the pod&#39;s full current commitments; in this supported mode the parent writer owns current task portfolio interventions. - Evidence: tasksApi.ts; V2PodBoard.tsx; taskEventService.ts; agentStateService.ts. - Basis: explicit + structural. - Confidence: medium. - Caveats: P refers only to the pod-scoped human task-board current-control loop; it does not infer organization-level governance for all pods or the maintainer community.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S3* / direct audit: - State: ? - Function: a complementary audit of reported agent task completion by an independent access route; not established from reviewed surfaces. - Disturbance / variety regulated: incorrect completion reports, ungrounded answers or unverified PR/task artefacts. - Decisive decision or feedback right: not established: the inspected audit logs/task updates provide evidence and visibility but no separate challenge owner and independently returned correction path was reconstructed. - Decision owner: unresolved; human users can view records, but that alone is not a credited complementary audit system. - Supporting / enforcement mechanisms: task change history, AuditLog, and agent ensemble observers are available instrumentation/roles without a proven independent direct-source audit procedure. - Closure path: no concrete independent audit finding → controller correction → changed S1 path verified. - Boundary reachability: the reviewed runtime, task board, audit logging and ensemble turn scheduler do not suffice for positive credit; additional first-party modules might alter this. - Why this is / is not agent-owned: storage/observability and routine multi-agent conversation alone cannot substitute for a contrasting evidence-access/independent reviewer. - Evidence: agentEnsembleService.ts; tasksApi.ts; AuditLog.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: prospective external-environment sensing and adaptation of the pod&#39;s future operating capability remains unresolved. - Disturbance / variety regulated: new external requirements, provider/capability shifts and future team needs. - Decisive decision or feedback right: unproven; scheduled summaries, memories, marketplace/installables and heartbeats do not by themselves settle adaptation choices or close them back into present capability. - Decision owner: unknown. Users can install/configure seats and models can remember information, but the S4 decision loop is not evidenced. - Supporting / enforcement mechanisms: pod-summarizer, long-term memory, scheduler, installable app registry, config APIs. - Closure path: no witnessed external distinction → prospective option → legitimate decision → changed pod operational capability loop. - Boundary reachability: shipped native summaries and memory exist but have not been connected into a decisive prospective adaptation loop. - Why this is / is not agent-owned: a retrospective digest and static memory are not sufficient for agent-owned or parent-owned S4. - Evidence: schedulerService.ts; agentMemoryService.ts; index.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S5 / identity: - State: ? - Function: whole-pod identity/ultimate-policy resolution, beyond permissions and individual operational approvals, remains unverified. - Disturbance / variety regulated: conflicts about ultimate pod purpose, legitimate authority and constitution of the shared organization. - Decisive decision or feedback right: operator owns pod configuration, membership and grants; operational action approvals exist, but no identity-level issue → authoritative decision → returned governing operation chain was reconstructed. - Decision owner: the human pod creator/operator owns configuration and grants; ownership of a function-specific S5 loop has not been established. - Supporting / enforcement mechanisms: membership roles, pod configuration, tool grants, approval/decision requests and their enforcement. - Closure path: tool-level and connector-grant approvals can change allowed actions, but they do not necessarily settle the ultimate identity/policy question of the pod. - Boundary reachability: supported self-hosted UI, pod and service-grant routes were inspected; no identity-level S5 mode is asserted. - Why this is / is not agent-owned: human-administered permissions are not automatically S5=P; no model-owned ultimate-identity authority demonstrated. - Evidence: grants.ts; decisionRequestService.ts; pods.ts; roomGrantService.ts. - Basis: explicit + structural + unknown. - Confidence: medium (in unresolved closure). - Caveats: Inspected support mechanisms do not justify a confident positive state; uncertainty is not a universal absence claim.\">?</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b900d7b45fa741f16191894f9788429f7af5b294/assessments/commonly.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b900d7b45fa741f16191894f9788429f7af5b294\">b900d7b &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/cloudflare/agents\" target=\"_blank\" rel=\"noopener\">Cloudflare Agents</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/cloudflare/agents/tree/46760e635ce9599add0abbfe6c1a34af0d5d44f1\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 46760e635ce9599add0abbfe6c1a34af0d5d44f1\">46760e6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: first-party agent instances can autonomously execute model/tool behavior over persistent state and scheduled/event-driven work.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: agent-to-agent calls, workflows and subagent composition provide communication/delegation, but no distinct function was found that regulates interference or shared constraints among autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: Durable Object lifecycle, routing and scheduling are runtime infrastructure. They do not establish whole-system managerial authority over operational commitments/resources in the VSM sense.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: observability/state persistence does not create an independent complementary audit channel; no such first-party organizational function was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: scheduling and event processing concern execution timing, not prospective environmental intelligence and adaptation of system capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: topology, tools, prompts, access and policies are application/developer supplied. No autonomous ultimate policy/identity function is included.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/cloudflare-agents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-29T18:03:26+03:00\"><th scope=\"row\"><a href=\"https://github.com/ever-works/ever-works\" target=\"_blank\" rel=\"noopener\">Ever Works</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-29\">2026-10-29</time></td><td class=\"review-ref\"><a href=\"https://github.com/ever-works/ever-works/tree/e159e7c6ff34fdacbd8967ad92ae42e3311b444b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision e159e7c6ff34fdacbd8967ad92ae42e3311b444b\">e159e7c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: first-party model-selected tool work with observation feedback and optional continuation, scheduled/heartbeat triggers and task outputs. - Disturbance / variety regulated: open-ended user/tenant tasks, web/search data, tool responses, generated work outcomes, errors, steering messages and budget/context limits. - Decisive decision or feedback right: choose the next recognized tool calls or final response, interpret returned result messages and re-enter inference; model-selected graph decisions can also advance a configured task workflow. - Decision owner: model-backed AI run inside AgentRunService through AgentAiDispatchFacade, not the BullMQ/Trigger scheduling service or static AGENTTEMPLATES. - Supporting / enforcement mechanisms: prompt assembly, provider facade, tool descriptions and grants, invokeTool, run logs/capture, budget/loop caps, steering, cancellation and tool-result trust fencing. - Closure path: assembled prompt → model dispatch → emitted tool calls → bounded approved tool execution → result serialized as the next tool message → further model round or final answer, with generated artifacts and outcome recorded for subsequent runs. - Boundary reachability: the runtime&#39;s actual runToolLoopInner implements this cycle using shipped service dependencies and default plugin path; model credentials and a task/agent instance are installer/tenant inputs. - Why this is / is not agent-owned: model output determines substantive task actions from the tools exposed; first-party deterministic middleware controls which actions execute but does not decide the work plan. - Evidence: agent-run.service.ts, AI dispatch, tool service, workflow graph. - Basis: structural. - Confidence: high. - Caveats: Source-path evidence only; no external LLM API, SaaS tenant, Trigger.dev job or generated site was run during assessment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no separately evidenced ongoing inter-S1 interference and a coordinating relation that returns a corrective adjustment to the participating operating units. - Disturbance / variety regulated: role/agent assignment ambiguity, multiple agents receiving tasks, concurrent scheduled runs, shared Work repository operations and task routing. - Decisive decision or feedback right: coordinator template may send a request to one lane or escalate ambiguity; scope/task permissions, per-agent run brakes, message queues and initial roster constraints enforce individual work boundaries. A concrete clash and closed reciprocal adjustment between two distinct running S1s is not established. - Decision owner: configured human/team task owner or optional coordinator task agent for ordinary routing; deterministic dispatch, budget, lock and roster logic for enforcement. - Supporting / enforcement mechanisms: workspace-coordinator template, first-party roster proposals, delegation API, task assignment, inbox and dispatch admission gate. - Closure path: task arrives → model may select a role/delegate → child task result returns to requester, or unresolved assignment asks a human. This is delegation and task intake, not source-confirmed dampening of inter-S1 oscillation/collision. - Why this is / is not agent-owned: a coordinator title, single lane per role, or multiple agents in a chart does not satisfy the specific distinct-S1/interference/attenuation/feedback requirement. - Evidence: agent templates, roster blueprints, sub-agent delegation, run dispatch gate. - Basis: structural. - Confidence: medium-high. - Caveats: A deployed tenant&#39;s mission roster could implement coordination with proper collision evidence; no such execution/contract is silently imported.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no source-confirmed dedicated present whole-system manager with broad operational view and decision power over competing current unit commitments/resources. - Disturbance / variety regulated: agent tool budgets, per-run credits, tenant policy, task status, schedule and approval holds, retries and questionable run outcomes. - Decisive decision or feedback right: AgentBrakeService blocks an individual paused/archived agent, run dispatch enforces current eligibility, guardrails halt particular risky tools, escalation records send a case to the user. No evidenced first-party regulator reviews the collective work state and reallocates shared commitments/priority in response to conflicts. - Decision owner: external tenant owner for budgets/rights/approval, deterministic admission/guardrail services for enforcement and task model for ordinary delegated work. - Supporting / enforcement mechanisms: run admission chain, per-agent status brake, usage ledger, budgets, agent escalation queue and task/work status dashboard. - Closure path: one run is admitted, parked, stopped, resumed or handed an approval answer; this controls an S1 action, but does not show whole-system current arbitration and returned cross-unit commitment changes. - Why this is / is not agent-owned: aggregate dashboards, a coordinator template that routes work, and an owner approval queue are not sufficient for S3 without a whole-system feedback/decision relation. - Evidence: agent-brake.service.ts, run dispatch gate, agent escalation, roster. - Basis: structural. - Confidence: medium-high. - Caveats: No tenant-wide resource-negotiating runtime controller was evidenced at the pinned revision.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no separately mandated complementary audit based on alternative operational access that challenges S3 current management and returns findings to its regulator. - Disturbance / variety regulated: code defects, CI failures, review-agent disagreement, missing review brief and usage/logging inconsistencies. - Decisive decision or feedback right: review agent receives a task diff and CI verdict, then approves or requests fixes in normal delivery; run ledger/test outputs record facts for developers/owner. - Decision owner: review task agent, ordinary CI, owner and developer tests; not a separately scoped S3 audit observer. - Supporting / enforcement mechanisms: reviewer-agent stage, fresh review brief guard, task-reviewer records, run trace, logs and test suites. - Closure path: review feedback can change the implementation task before completion, and a missing brief blocks a retry. This is primary QA/production feedback, not an independent audit of current operational management. - Why this is / is not agent-owned: second-agent review in an ordinary mandatory artifact path remains task quality control unless alternative access and control-return are established. - Evidence: agent-run reviewer brief gate, reviewer records, run ledger. - Basis: structural. - Confidence: high. - Caveats: The source&#39;s fail-closed reviewer retry prevents hallucinated verdicts; that is strong QA enforcement but not proof of a separate S3 organ.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no shipped prospective external/future adaptation loop returning options to the running platform/tenant&#39;s present S3 capability. - Disturbance / variety regulated: market changes, competitor news, content aging, ongoing user business goals and knowledge/work updates. - Decisive decision or feedback right: a configurable competitive analyst template can research changing external conditions and draft digest content; scheduled pipelines regenerate user-owned work, but no evidence that such intelligence proposes systemic adaptations which a current S3 evaluates/adopts through reciprocal capability feedback. - Decision owner: task model or optional market-watch agent for commissioned research; external tenant owner for actual strategy/capability decisions. - Supporting / enforcement mechanisms: competitive-analyst template, search plugins, run schedules, pipeline/generator stages, knowledge/memory. - Closure path: public-source search → model-generated digest or content → reviewable artifact/scheduled refresh. This is S1 output delivery; no S4-to-S3 organizational adaptation choice and return is wired. - Why this is / is not agent-owned: future-looking research content and continuous site improvement do not necessarily regulate the future viability of the operating system itself. - Evidence: competitive analyst template, pipeline executor, workflow graph. - Basis: structural. - Confidence: medium-high. - Caveats: A specialized tenant can create a future-analysis and policy adaptation process, but that configuration and its closed loop are not pinned in this repository.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no demonstrated ultimate identity/mandate decision and continuing authoritative return at the assessed tenant/agent-system recursion. - Disturbance / variety regulated: agent prompt identity, tenant role and scope, tool permissions, spend approval, guardrail violations and human escalation cases. - Decisive decision or feedback right: tenant owner sets prompt/permission/budget, approves a particular tool/action or responds to a stopped run. This is real authorization; no first-party path raises an S3–S4/organizational identity conflict to a legitimate final authority and applies a new governing mandate. - Decision owner: external tenant/mission owner for role definition and ordinary permissions; deterministic budget, policy/approval and escalation components for enforcement. - Supporting / enforcement mechanisms: SOUL.md/AGENTS.md role descriptions, scope/permission checks, guardrails, action proposals, human-owned escalation and result attribution. - Closure path: a tool/action failure creates an escalation → human note can resolve it and resume the parked run. Agent-proposed resolution is labeled as such and does not masquerade as the owner&#39;s instruction; no demonstrated constitutional identity question or authoritative system-policy return exists. - Why this is / is not agent-owned: no account/role-setting UI, editable agent identity prompt or human pause/approval by itself meets S5 identity adjudication closure. - Evidence: agent escalation service, agent templates, guardrails, agent action proposal. - Basis: structural. - Confidence: medium-high. - Caveats: Human real-world business/tenant policy may be a separate parent S5, but the assessment cannot impute that organization&#39;s actual adjudications from installed templates or permission fields.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/395332d779f8b714c384ebcba5265e639954ef2a/assessments/ev/ever-works.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 395332d779f8b714c384ebcba5265e639954ef2a\">395332d &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/huggingface/smolagents\" target=\"_blank\" rel=\"noopener\">smolagents</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/huggingface/smolagents/tree/30bb1161095dbae2271e6bc3cc4c219cc3897a57\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 30bb1161095dbae2271e6bc3cc4c219cc3897a57\">30bb116 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: tool/code agents autonomously choose and execute task actions within configured bounds.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: managed-agent delegation does not itself regulate interference among peer autonomous S1 units. No separate anti-conflict/anti-oscillation or shared-constraint coordination function was established; the earlier S2=C interpretation is therefore removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: a manager agent assigning work is still task execution. The reviewed runtime does not provide whole-system authority for current resource, capacity or commitment regulation across S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit channel separate from routine agent execution was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: agent planning and delegation operate on the current objective; no distinct prospective environmental intelligence function was found.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: prompts, tools, managed-agent topology and permissions are parent/developer configured rather than determined by an autonomous policy/identity authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/smolagents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-19T15:20:54+03:00\"><th scope=\"row\"><a href=\"https://github.com/balrog-ai/BALROG\" target=\"_blank\" rel=\"noopener\">BALROG</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/balrog-ai/BALROG/tree/b7afe79e3e4265811cfa985ed7c95c4d1a11e3f5\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b7afe79e3e4265811cfa985ed7c95c4d1a11e3f5\">b7afe79 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Decide and enact the next game action in an interactive episode, conditioned on observations and previous actions. - Disturbance / variety regulated: Changing mission/world state, partial observation, invalid/ineffective actions, terminal conditions and long-horizon task uncertainty. - Decisive decision or feedback right: The model-backed first-party agent selects the action returned by act(); the evaluator routes the validated action to the game and exposes the resulting next observation/reward. - Decision owner: The configured agent/model acting through the shipped AgentFactory and NaiveAgent / other real shipped agent modes. The external LLM supplies cognition to this wired first-party operating path, not independent higher-recursion control. - Supporting / enforcement mechanisms: Prompt/history builders, model API client/retries, evaluator episode iterator, environment action validator, save/logging and terminal-step limits. - Closure path: Observation + history → model-backed act() → extracted game action → environment validity check and step() → new observation/invalid-action feedback → subsequent act(). - Boundary reachability: The public python eval.py agent.type=naive ... command wires AgentFactory into EvaluatorManager.run(), which calls Evaluator.runepisode() and the first-party act() method for each step. Model inference is externally provided but the action/feedback path is standard packaged functionality, not a sample-only diagram. - Why this is / is not agent-owned: In supported model-backed modes the next action is selected on current observation/context by the agent&#39;s configured inference; deterministic evaluator logic enforces the action interface and reports world state but does not select the substantive action. - Evidence: eval.py; balrog/agents/init.py; balrog/agents/naive.py; balrog/agents/chainofthought.py; balrog/evaluator.py; balrog/config/config.yaml. - Basis: Explicit source control/feedback loop with configurable model-backed agent choice. - Confidence: High for shipped structural mode, not an experimental success-rate claim. - Caveats: dummy/illustrative demo or absent/nonfunctional external model does not by itself prove active agent ownership. This positive is for supported configured model-backed play, not benchmark orchestration.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No evidenced first-party regulation of interference among distinct independently viable game-playing S1 units. - Disturbance / variety regulated: Parallel episode workloads may share CPU/API budget or output directories, but the benchmark&#39;s partitioned tasks, worker queue and result aggregation do not demonstrate oscillatory inter-S1 conflict and adaptive damping into participating agents. - Decisive decision or feedback right: Multiprocessing queues and numworkers dispatch episodes according to preset researcher configuration; no separate coordination actor judges specific inter-S1 conflicts and returns corrective constraints. - Decision owner: EvaluatorManager deterministic scheduling/configured worker count, not an autonomous S2 agent. - Supporting / enforcement mechanisms: Task queues, results queue, episode identity, file paths and progress logging. - Closure path: Episode jobs run and results return to the evaluator, not an inter-agent interference → coordination decision → changed later behavior loop. - Why this is / is not agent-owned: Multiple benchmark episodes/workers are evaluation replicas, not the autonomous operational divisions whose interference S2 would regulate. - Evidence: balrog/evaluator.py; eval.py; balrog/config/config.yaml. - Basis: Bounded absence after inspecting shipped episode scheduler and first-party agent paths. - Confidence: High at the declared boundary. - Caveats: An external multi-agent gaming organization would require a separate assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-game-playing-organization current-control loop is established at the declared agent recursion. - Disturbance / variety regulated: Resource contention, stop conditions, task mix and experiment scheduling remain parameters of the external evaluator/researcher rather than operational decisions of an agent-owned whole-current executive. - Decisive decision or feedback right: The researcher configures workers, episodes, tasks, model; the evaluator deterministically executes, records and stops episodes. The agent chooses local game moves but not whole-system resource/commitment allocations. - Decision owner: Experiment configuration and scripted evaluator, outside credited S3 ownership. - Supporting / enforcement mechanisms: Hydra config, fixed limits, worker scheduler, saved run state and episode termination. - Closure path: No sensed whole-system current condition → legitimate S3 resource/intervention decision → returned operational adjustments. - Why this is / is not agent-owned: Having centralized visibility of benchmark progress or a maximum episode length is not S3 decisive authority. - Evidence: balrog/evaluator.py; balrog/config/config.yaml; eval.py. - Basis: Bounded negative for agent operating recursion. - Confidence: High for shipped modes. - Caveats: Researcher administration of benchmark infrastructure is not the assessed agent&#39;s first-party S3 parent mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independently corrective organizational audit with a return path into this agent cell is established. - Disturbance / variety regulated: Evaluator sees rewards, episode failures and action validity; these observations document task performance but do not constitute an auditor independently checking organizational claims and changing later operating regulation. - Decisive decision or feedback right: Environment validity correction is part of the ordinary game action loop; offline recorded scores/statistics are not independently owned audit judgments with corrective operational closure. - Decision owner: Environment rules and evaluator recordkeeping, not a separate autonomous complementary auditor. - Supporting / enforcement mechanisms: Episode CSV/JSON logs, scoring, invalid-action string feedback and summary table. - Closure path: No complementary independent inspection → audit verdict → accountable agent/controller corrective response. Environment observation feedback belongs to S1. - Why this is / is not agent-owned: Recording a score, parsing validity or writing telemetry is not an organizational audit with independent judgment and corrective authority. - Evidence: balrog/evaluator.py; eval.py; balrog/config/config.yaml. - Basis: Bounded negative after checking scoring, feedback and agent integration. - Confidence: Medium-high; only code-level evidence, no runtime attestation. - Caveats: External research audit of model behavior is outside this game-playing agent boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party external-prospective scan/option/selection/adoption loop updates future game-playing capability at the stated boundary. - Disturbance / variety regulated: Unseen future games may expose policy deficiencies, but the shipped first-party loop reacts inside each episode, while future policy/prompt changes belong to external authors or prepared demonstrations. - Decisive decision or feedback right: Fixed operator-set agent.type and ICL dataset determine which preexisting behavior scaffold is used; the game-playing agent does not decide to modify its own later operating capability based on future/environmental opportunity assessments. - Decision owner: Researcher/author supplies prompt, sample records, client and benchmark settings; first-party code loads them. - Supporting / enforcement mechanisms: History buffering, optional CoT, few-shot replay, demonstration selection and caching. - Closure path: Past fixed episodes may be inserted into a current prompt, but no observed external trend → proposed future adaptation → adopted persistent capability change → return into later operations is shown. - Why this is / is not agent-owned: Memory, in-episode plan refinement and preloaded demonstrations do not alone confer S4 organizational adaptation ownership. - Evidence: balrog/agents/fewshot.py; balrog/dataset.py; balrog/agents/chainofthought.py; balrog/evaluator.py; balrog/config/config.yaml. - Basis: Bounded source negative; specifically checked the shipped optional ICL mode. - Confidence: Medium-high at the declared boundary. - Caveats: A separately built online-learning controller using BALROG evaluation output would be a different system-in-focus.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party autonomous or operationally closed parent identity/ultimate-policy function for the game-playing organization. - Disturbance / variety regulated: Which environments, model/providers, prompts, eval goals and stopping rules define the experiment is set by upstream config/researchers outside an assessed runtime identity/policy-return organ. - Decisive decision or feedback right: Evaluated agent receives its configured role/task; its moves do not decide the identity/purpose or ultimate policy of the whole organization. - Decision owner: Researcher/maintainer/operator configures purpose and authority; no live first-party legitimate S5 decision/return process is established. - Supporting / enforcement mechanisms: Hydra config, static prompt instructions, environment mission and terminal control. - Closure path: No runtime identity/ultimate-policy case → legitimate authority → policy decision → return to subsequent game-playing operation; static startup settings alone do not provide a qualifying parent mode. - Why this is / is not agent-owned: Constraints and instructions limit S1 actions without a first-party S5 governance loop. - Evidence: balrog/config/config.yaml; eval.py; balrog/agents/init.py; balrog/agents/naive.py. - Basis: Bounded negative at the declared standard distribution. - Confidence: High for reviewed runtime, without external governance inference. - Caveats: Repository maintainers and external organizations may exercise policy rights over experiments but are not shipped parent closure of the assessed agent.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/63e7c851e91ad868c72dc318e860aefd7b6eb56f/assessments/ba/balrog.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 63e7c851e91ad868c72dc318e860aefd7b6eb56f\">63e7c85 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-18T19:32:34+03:00\"><th scope=\"row\"><a href=\"https://github.com/ag2ai/ag2\" target=\"_blank\" rel=\"noopener\">AG2</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-18\">2026-09-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/ag2ai/ag2/tree/3211bb19832049e7abe1a5742b6d177274bff723\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3211bb19832049e7abe1a5742b6d177274bff723\">3211bb1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A. - Function: autonomous agent loops perform the primary task transformation through model decisions and tool actions. - Disturbance / variety regulated: user/task uncertainty, model outputs, tool/environment feedback, persistent conversational state and task-local exceptions. - Decisive decision or feedback right: choose the next model/tool action and revise the trajectory from returned observations. - Decision owner: the model-driven Agent actor. - Supporting / enforcement mechanisms: stream/history, tool execution, middleware, response validation, optional knowledge/assembly, subtask tools and runtime cancellation. - Closure path: tool/model results are appended to the run/stream and enter later model requests, changing subsequent action. - Why agent-owned: first-party source defines Agent as the agentic unit that runs the model loop and invokes tools; the README describes the model deciding when to call tools. - Evidence: README and ag2/agent.py at the pinned revision. - Basis: explicit and structural. - Confidence: high. - Caveats: developer configuration constrains prompts/tools/providers, but the operational choice within those bounds remains model-owned.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C. - Distinct S1 units: two or more autonomous Agent instances participating in a Network discussion. - Specific inter-S1 disturbance: multiple participants share one conversational work channel and can otherwise attempt to speak out of sequence or stall an expected turn, producing conversational collision/oscillation and blocking progress. - Coordination relation: the first-party DiscussionAdapter snapshots participant order, exposes one expectednextspeaker, rejects any out-of-turn EVTEXT, rotates the expected speaker after each accepted message, and publishes turnwithin expectations for delayed turns. - Disturbance attenuation: deterministic Hub/adapter enforcement serializes the common conversational floor; expectation feedback can warn or hide a participant that fails to take its expected turn. - Decisive decision or feedback right: the supplied protocol determines which participant may speak next and whether an attempted send is admissible; the developer chooses to compose the agents into this discussion mode rather than an autonomous agent choosing the coordination rule. - Decision owner: first-party deterministic runtime / developer-composed channel protocol, not an autonomous coordinating agent. - Supporting / enforcement mechanisms: authoritative Hub state, channel WAL, adapter state folding, validation, expectation sweeper and violation handlers. - Closure path: accepted turns advance expectednextspeaker; rejected out-of-turn sends return a protocol error; expectation violations feed channel warnings/hiding back into later participant behavior. - Why this is S2-specific rather than generic messaging: the primitive is explicitly a multi-participant turn-taking regulator with an evidenced collision/stall mode and enforced feedback, not merely a mailbox/router/graph edge. The standard distribution supplies the regulation, but autonomous coordination ownership must still be composed, so the publication state is C, not A. - Evidence: Network overview and DiscussionAdapter implementation. - Basis: explicit and structural. - Confidence: high. - Caveats: conversation free-form messaging and generic workflow sequencing are not independently promoted to S2; the positive claim rests on the concrete discussion turn-regulation path.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: —. - Function finding: the Hub centralizes current network state and enforces rules, but no first-party actor/path was established that combines a whole-system current view with discretionary authority over shared resources, commitments, priorities, accountability or intervention on behalf of the organization as a whole. - Disturbance / variety regulated: access limits, inbox pressure, delegation depth, channel counts and TTLs are runtime constraints, not by themselves S3 organizational decisions. - Decisive decision or feedback right: not established for S3. The default RuleBasedArbiter applies tenant/developer-selected rules; custom HubArbiter subclasses are extension points whose S3 semantics, if any, belong to downstream composition. - Decision owner: not established. - Supporting / enforcement mechanisms: Hub health(), registry/channel state, Rule, RuleBasedArbiter, rate/inbox/access checks, TTL/expectation sweepers and HITL hooks. - Closure path: the runtime can allow/deny individual network actions and auto-close channels, but this closes enforcement decisions selected elsewhere rather than a first-party whole-system current-control loop. - Why not C: a generic/customizable policy gate plus central telemetry does not establish the S3 function before autonomy classification. The developer would need to supply the whole-system regulatory judgment itself, not merely its autonomous owner. - Evidence: Hub/Identity and Governance/Audit documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream application can implement an S3-capable arbiter or manager against these primitives; that composed system requires its own assessment boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: —. - Claim being audited: channel/rule/expectation events and operational state are recorded by the Hub audit/listener path. - Ordinary reporting path: the Hub&#39;s own registry, WAL, state transitions and expectation evaluators. - Complementary access path: none established. The built-in AuditLog is itself a Hub listener receiving the same committed transitions, and expectation evaluators inspect the same channel metadata/WAL state. - Independence boundary: no materially independent operational-evidence path is supplied by default. - Decisive audit judgment / owner: not established. - Supporting / enforcement mechanisms: append-only audit log, HubListener, expectation evaluators, task observations and custom listener hooks. - Closure path: expectation violations can warn/close channels, but that is ordinary protocol monitoring/enforcement rather than complementary independent audit. - Why not C: custom listeners/evaluators can be attached, but the standard distribution does not supply an S3-specific independent evidence/judgment path; generic extension is insufficient. - Evidence: Governance/Audit documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream independent auditor using different evidence could establish S3 in a composed system.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: —. - External distinction: agents can use tools and external services during current task execution. - Future/prospective distinction: no distinct first-party environmental/future model was established for organizational adaptation. - Adaptation option generated: none at the harness-organization capability level. - Path back into current capability / S3: none established. - Decision owner: not applicable. - Supporting mechanisms: persistent knowledge, history compaction/assembly, observed capability statistics, tools, middleware and application-defined workflows. - Closure path: those mechanisms alter context or record retrospective performance, but no outside-and-then adaptation loop is supplied. - Evidence: agent harness and Hub/Identity surfaces reviewed at the pin. - Basis: structural. - Confidence: high. - Caveats: learning, compaction, retrospective task statistics and current external tool use are not S4 by themselves.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: —. - Identity / ultimate-policy issue: no first-party runtime path was established for resolving identity/ultimate-policy tensions for the configured agent organization. - Ultimate authority: developers/operators select prompts, models, tools, passports, rules, auth adapters, channel manifests and HITL hooks; those configuration choices are not themselves a runtime S5 loop. - Decisive decision or feedback right: no identity/ultimate-policy issue-to-authority-to-return path was established. - Supporting / enforcement mechanisms: Passport, Rule, authentication, access/limit enforcement, system prompts and human approval hooks. - Return-to-operation path: ordinary HITL approval returns to the current tool trajectory, but the documented cases are task/safety approvals rather than identity-level policy closure. - Why not C or P: configurable policy/enforcement surfaces and generic human approval do not establish S5 before ownership is classified. - Evidence: Hub/Identity and HITL documentation. - Basis: structural. - Confidence: high. - Caveats: a downstream organization may place ultimate policy at a human or institutional parent, but AG2 does not establish that function at this reviewed boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/dd2d14532e5ce959a06f0c4cb41677411cb03806/assessments/ag2.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit dd2d14532e5ce959a06f0c4cb41677411cb03806\">dd2d145 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:29:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/RooCodeInc/Roo-Code\" target=\"_blank\" rel=\"noopener\">Roo Code</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/RooCodeInc/Roo-Code/tree/b867ec9145750d0ae1ff7f02d35406e9bf2a0b16\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b867ec9145750d0ae1ff7f02d35406e9bf2a0b16\">b867ec9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the normal coding agent autonomously selects/executes tools and reacts to results inside configured permissions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: newtask is parent-to-child delegation. The reviewed implementation does not show a distinct function that regulates conflicts, oscillation or shared constraints between multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: parent task ownership and child-task lifecycle do not establish whole-system current authority over resources/commitments across multiple S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit path distinct from the normal operational hierarchy was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: mode selection and task decomposition are current-task planning, not a separate prospective environment-intelligence/adaptation function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: modes, permissions, rules and task goals are configured by the user/developer. No autonomous ultimate policy/identity authority is present.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/981ed777406ce897fdfd0656df0edf9341f93d65/assessments/roo-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 981ed777406ce897fdfd0656df0edf9341f93d65\">981ed77 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:01:12+03:00\"><th scope=\"row\"><a href=\"https://github.com/browser-use/browser-use\" target=\"_blank\" rel=\"noopener\">Browser Use</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/browser-use/browser-use/tree/50f205533fe10ba35b553d2a3689c77b87bd5d0a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 50f205533fe10ba35b553d2a3689c77b87bd5d0a\">50f2055 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the standard agent autonomously chooses browser/tool actions and continues from environment feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: no distinct mechanism was found for regulating interference among multiple autonomous S1 units. A single browser-agent loop with callbacks is not S2.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: run state, history and task-level planning manage one operational process; there is no whole-system current-control authority over multiple S1 commitments/resources.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the optional judge evaluates the operational trajectory/output inside the normal run. It is not evidenced as an organizationally independent or complementary audit channel with distinct access/authority.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: task planning predicts next actions for the current browser objective. No separate environment-scanning function that changes system capability or strategy over a longer horizon was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: tool permissions, task goals, prompts and approval/configuration remain externally supplied rather than owned by an autonomous policy/identity function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d3c36ab7c17230290253c004628399e193b7f685/assessments/browser-use.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d3c36ab7c17230290253c004628399e193b7f685\">d3c36ab &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-27T20:53:53+03:00\"><th scope=\"row\"><a href=\"https://github.com/vortezwohl/Autono\" target=\"_blank\" rel=\"noopener\">Autono</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-27\">2026-10-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/vortezwohl/Autono/tree/ebc66d3d9cd5c2a802af8b531af67a1b70c56a63\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ebc66d3d9cd5c2a802af8b531af67a1b70c56a63\">ebc66d3 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Produce request-solving outcomes through first-party model/ability feedback iteration. - Disturbance / variety regulated: Changing intermediate results, incomplete requests, unavailable capabilities and task-specific action arguments. - Decisive decision or feedback right: Choose the next available ability/arguments or task-complete/failure response using current request/history. - Decision owner: The model-backed Agent or McpAgent. - Supporting / enforcement mechanisms: Ability registration, JSON/format parsing, ExecutorPrompt tool invocation, action memory, MCP transport and stochastic termination enforcement. - Closure path: NextMovePrompt selects action → execute callable/MCP tool → summarize and memorize returned result → next choice; terminal choice/abandonment returns AllDoneMessage. - Why this is / is not agent-owned: Removing the model preserves tools and enforcement but removes task-specific action selection. The developer supplies task abilities without needing to implement the autonomous loop. - Evidence: autono/init.py; autono/brain/agent.py; autono/brain/mcpagent.py; autono/prompt/nextmoveprompt.py; autono/prompt/executorprompt.py; README.md - Basis: structural - Confidence: high within the declared source boundary - Caveats: A is structural runtime ownership, not a claim of robust task performance or guaranteed completion; constructor/introduction/model calls were not executed here. - Boundary reachability: Autono exports Agent/McpAgent and first-party ability/delegation constructors; README&#39;s instantiate→assign→justdoit path directly enters the shipped loop.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No specific inter-S1 conflict-regulation path established beyond delegation and memory transfer. - Disturbance / variety regulated: A call tree may contain multiple task agents; historical progress can inform later steps. - Decisive decision or feedback right: No qualifying first-party decisive right established for this function. - Decision owner: No qualifying owner at the declared boundary. - Supporting / enforcement mechanisms: The cited runtime and documentation are supporting surfaces, not decision owners. - Closure path: No function-specific returned closure at this boundary. - Why this is / is not agent-owned: Nested ability calls, copied memory, chronological progress reasoning and division of labour do not identify a concrete interaction conflict plus a coordination discretion/return path. - Evidence: autono/ability/agenticability.py; autono/ability/mcpagenticability.py; autono/brain/memoryaugment.py; autono/prompt/nextmoveprompt.py; demo/multiagent.py - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-current organizational control loop in the shipped runtime. - Disturbance / variety regulated: Excess steps and unsuitable abilities can waste a task&#39;s effort. - Decisive decision or feedback right: No qualifying first-party decisive right established for this function. - Decision owner: No qualifying owner at the declared boundary. - Supporting / enforcement mechanisms: The cited runtime and documentation are supporting surfaces, not decision owners. - Closure path: No function-specific returned closure at this boundary. - Why this is / is not agent-owned: Probabilistic stopping, expected-step estimation, personality and grant/deprive APIs constrain local execution; they do not assign a whole-system resource/commitment decision owner. - Evidence: autono/brain/agent.py; autono/brain/baseagent.py; autono/brain/mcpagent.py; autono/brain/hook/beforeactiontaken.py; README.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No complementary independent audit of agent success claims. - Disturbance / variety regulated: The model&#39;s own summaries may omit or misread operational facts. - Decisive decision or feedback right: No qualifying first-party decisive right established for this function. - Decision owner: No qualifying owner at the declared boundary. - Supporting / enforcement mechanisms: The cited runtime and documentation are supporting surfaces, not decision owners. - Closure path: No function-specific returned closure at this boundary. - Why this is / is not agent-owned: Executor summaries and final introspection use the acting model/history; observability hooks are developer callbacks, not an independent audit-specific access/judgment/control path. - Evidence: autono/prompt/executorprompt.py; autono/prompt/introspectionprompt.py; autono/brain/hook/basehook.py; autono/brain/hook/afteractiontaken.py; demo/multiagent.py; README.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No external-and-prospective capability adaptation loop. - Disturbance / variety regulated: Requests and external tool results vary; model/tool selection may be customized. - Decisive decision or feedback right: No qualifying first-party decisive right established for this function. - Decision owner: No qualifying owner at the declared boundary. - Supporting / enforcement mechanisms: The cited runtime and documentation are supporting surfaces, not decision owners. - Closure path: No function-specific returned closure at this boundary. - Why this is / is not agent-owned: Dynamic next actions, planning, memory transfer and self-introduction solve the current request. They do not develop future-environment options and couple them to present capability regulation. - Evidence: autono/prompt/schedulerprompt.py; autono/prompt/nextmoveprompt.py; autono/brain/memoryaugment.py; autono/brain/baseagent.py; README.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No identity/ultimate-policy decision-and-return path. - Disturbance / variety regulated: Agent names, abilities, personalities and hook rules bound operation. - Decisive decision or feedback right: No qualifying first-party decisive right established for this function. - Decision owner: No qualifying owner at the declared boundary. - Supporting / enforcement mechanisms: The cited runtime and documentation are supporting surfaces, not decision owners. - Closure path: No function-specific returned closure at this boundary. - Why this is / is not agent-owned: Generated self-introduction describes the assigned ability set; it does not decide legitimate system identity or resolve ultimate policy. - Evidence: autono/brain/baseagent.py; autono/prompt/selfintroduce.py; autono/enum/Personality.py; autono/brain/hook/basehook.py; README.md - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/5ba837fe20690cc44781b988d68e06089e2111d0/assessments/au/autono.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 5ba837fe20690cc44781b988d68e06089e2111d0\">5ba837f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:15:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/superagentxai/superagentx\" target=\"_blank\" rel=\"noopener\">SuperAgentX</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/superagentxai/superagentx/tree/28f2759f20d2dba9fa184ca4fe6b50943388cfbc\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 28f2759f20d2dba9fa184ca4fe6b50943388cfbc\">28f2759 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: individual configured agents autonomously execute model/tool work within the workflow.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: sequencing, routing, parallel fan-out and result aggregation define workflow topology, but no dedicated mechanism was found that detects and regulates interference or instability among multiple autonomous S1 units. Therefore the earlier workflow-derived C interpretation is rejected.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: workflow state and routing do not amount to a whole-system current-control function with authority over shared resources, priorities and commitments across the viable system.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: persistence, logging and ordinary review/approval stages remain part of the configured operational workflow; no independent complementary audit channel was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: routing and workflow planning concern present task execution, not a distinct prospective environment-scanning/adaptation function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: human approval and governance configuration are parent authority. The harness does not autonomously own ultimate identity, values or policy.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0b75c7fb0539831a89e5ca33f4cf1df430f3550f/assessments/superagentx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0b75c7fb0539831a89e5ca33f4cf1df430f3550f\">0b75c7f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-24T20:48:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/humanlayer/agentcontrolplane\" target=\"_blank\" rel=\"noopener\">Agent Control Plane</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-24\">2026-09-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/humanlayer/agentcontrolplane/tree/eaa2a7ed1d9cb4e13dc53defaf420e36f481dcad\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision eaa2a7ed1d9cb4e13dc53defaf420e36f481dcad\">eaa2a7e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform a durable goal-directed agent task through repeated model decisions and asynchronous tool/environment interactions until a final answer or terminal failure. - Disturbance / variety regulated: task/user objective, changing context window, available MCP/human/sub-agent tools, model-selected tool calls, asynchronous tool outcomes, transient model/tool failures and child/human completion latency. - Decisive decision or feedback right: choose the next substantive answer/tool action from the current Task context, then incorporate returned tool observations into the next semantic decision. - Decision owner: the configured ACP Agent&#39;s model-driven Task loop implemented by first-party Task/ToolCall controllers. - Supporting / enforcement mechanisms: durable Task/ToolCall CRDs, phase state machines, first-party LLM client factory, tool adapters/executor, per-Task mutex/Lease, controller-runtime reconciliation, context persistence, retries and terminal-state handling. - Closure path: Task objective/context → first-party Task controller sends context/tools to configured model → model chooses final content or tool calls → ACP creates first-party ToolCall resources → MCP/sub-agent/human path returns results → ACP appends tool messages to Task context → Task returns to ReadyForLLM → next model decision or final answer. - Boundary reachability: acp/cmd/main.go registers both Task and ToolCall reconcilers in the standard controller manager; TaskReconciler.SetupWithManager binds the Task CRD and initializes the production state machine. - Why this is / is not agent-owned: deterministic controllers enforce durable progression, but substantive next-action selection comes from the Agent&#39;s configured model over first-party-maintained context and tool choices. Human approval is optional for configured MCP tools and does not remove the standard autonomous operation path. - Evidence: acp/cmd/main.go; acp/internal/controller/task/taskcontroller.go; acp/internal/controller/task/statemachine.go; acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/toolcall/executor.go. - Basis: explicit + structural. - Confidence: high. - Caveats: external model inference, MCP servers and humans are dependencies. Their internal functions are not inherited; the positive S1 claim rests on ACP&#39;s first-party ownership of the iterative operational closure around them.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party path establishes regulation of a concrete disturbance between distinct ACP S1 operational units with feedback that changes their subsequent mutual behaviour. - Disturbance / variety regulated: ACP supports multiple Agents/Tasks and parent-to-child delegation, but the frozen standard distribution does not identify a specific inter-S1 collision, contention, contradictory commitment or shared-resource disturbance whose attenuation forms a closed coordination relation. - Decisive decision or feedback right: not established as a distinct S2 right. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: child Task creation, parent/child labels, child-result polling, Task-specific mutexes and Kubernetes Leases. - Closure path: delegation closes parent operation → child Task → child result → parent operation, which is task decomposition/recursion. The Task Lease closes duplicate controller execution for one Task. Neither path demonstrates inter-S1 disturbance → attenuation → feedback into multiple S1 units. - Boundary reachability: delegation and Task leases are standard-runtime code, but their organizational function is not S2 under the Profile criteria. - Why this is / is not agent-owned: multiple agents and delegation are topology. A controller lease is infrastructure consistency. Neither supplies the required coordination function merely because it affects concurrency. - Evidence: acp/internal/controller/toolcall/executor.go; acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/task/statemachine.go; acp/api/v1alpha1/agenttypes.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: an adopter can define interacting Agents/tools whose domain creates coordination needs. Such an instantiated organization would require separate evidence; ACP&#39;s generic delegation mechanism does not itself close S2. - Distinct S1 units checked: parent and child ACP Tasks/Agents created through the built-in delegation tool. - Inter-S1 disturbance checked: no first-party contract was found for branch/resource collision, contradictory shared commitments, rate/resource interference or another disturbance between those Tasks. - Why generic communication/routing/delegation is insufficient: the child result is simply returned as the result of the parent&#39;s selected tool call; no function-specific attenuation of mutual disturbance is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party whole-system present-management loop is established across the running Agent/Task population. - Disturbance / variety regulated: individual Tasks are durably progressed and individual ToolCalls can be gated, retried or rejected; these controls do not provide a whole-current view with authority to allocate/reallocate resources or intervene across the operational organization as S3. - Decisive decision or feedback right: no first-party actor is shown receiving a whole-system current state and deciding present resource/work allocation or cross-unit intervention for the installation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: per-Task reconciler state, Task mutex/Lease, ToolCall approval, Agent/Task REST CRUD/list surfaces and Kubernetes controller manager. - Closure path: local Task state drives local reconciliation; configured human approval can decide whether one MCP call proceeds. No whole-system current-state → management judgment → intervention → changed organization-wide operation loop is established. - Boundary reachability: the cited local controls are standard runtime. Their presence is insufficient to change their organizational function into S3. - Why this is / is not agent-owned: durable supervision, retries, distributed locking and action approval are enforcement/operational mechanisms. No autonomous or parent current manager owns a whole-system S3 decision right at this boundary. - Evidence: acp/internal/controller/task/statemachine.go; acp/internal/controller/toolcall/statemachine.go; acp/api/v1alpha1/tasktypes.go; acp/internal/server/server.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: a user/operator can create, update or delete Agent definitions through API/Kubernetes surfaces, but generic administrative CRUD is not by itself a whole-current S3 function. - Whole-system current view checked: REST listing and Kubernetes resource observation expose state but no first-party current-management decision loop is bound to that view. - Current-control scope checked: no task priority, fleet quota, work reallocation or comparable whole-population management right was established in the reviewed Task/Agent contracts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material runtime path establishes an independent complementary audit of S1 operation with corrective return. - Disturbance / variety regulated: ACP records Kubernetes events/traces, validates resource dependencies and can require a human to approve a selected MCP call; these mechanisms observe or constrain the ordinary path but do not form a separate audit organization. - Decisive decision or feedback right: no independent auditor is shown judging operational claims/outcomes from materially complementary evidence and returning a corrective finding into subsequent operation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: status/events, OpenTelemetry spans, validation, human approval and repository-development review helpers outside the runtime boundary. - Closure path: runtime events/status support observability and approval may allow/reject a proposed tool call, but there is no independent audit finding → corrective action → re-observation loop over completed/ongoing work. - Boundary reachability: observability and approval are shipped; repository hack/ reviewer prompts are adjacent development material and excluded from runtime ownership. - Why this is / is not agent-owned: approval before an action executes is not complementary audit of operational reality, and telemetry does not own audit judgment merely because it records evidence. - Evidence: acp/internal/controller/toolcall/statemachine.go; acp/internal/controller/task/statemachine.go; acp/cmd/main.go. - Basis: structural negative search. - Confidence: high. - Caveats: an Agent may be configured by an adopter to act as a reviewer, but role/prompt configuration does not establish a standard-distribution S3 function without evidence of independence and corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party prospective adaptation loop is established in the shipped runtime. - Disturbance / variety regulated: ACP reacts to current model/tool errors, dependency readiness, human responses and child-task results, but those are present operational observations rather than outside/future intelligence that changes the organization&#39;s future capability or strategy. - Decisive decision or feedback right: no runtime owner is shown generating/evaluating a prospective adaptation option and returning the chosen change into current organizational capability. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: durable context window, retries, MCP discovery, Agent validation, human-contact tools and external model/tool inputs. - Closure path: not established. Current observations return to the same Task loop as operational context; they do not become an organization-level prospective adaptation that changes how ACP subsequently operates. - Boundary reachability: reviewed first-party runtime code contains adapters and reactive controllers but no separate learning/adaptation owner/path. - Why this is / is not agent-owned: memory/context persistence and access to humans/external tools can support S1 cognition without constituting S4. Future-facing function must be proven separately. - Evidence: acp/internal/controller/task/statemachine.go; acp/api/v1alpha1/tasktypes.go; acp/api/v1alpha1/agenttypes.go. - Basis: structural negative search. - Confidence: high. - Caveats: an application built on ACP can create a research/adaptation Agent organization. That downstream composition is a separate system-in-focus.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy closure is established at the ACP installation recursion. - Disturbance / variety regulated: Agent system prompts, model/tool configuration, sub-agent lists and MCP approval settings constrain operational behaviour, while users/operators can create/update resources; none is shown recognizing and resolving an organizational identity/ultimate-policy issue as S5. - Decisive decision or feedback right: no first-party path establishes identity/policy issue → legitimate ultimate authority → authoritative decision → return governing subsequent operation. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: Agent system prompt, Agent/LLM/MCP resource configuration, optional approval contact channel, Kubernetes/API administration and human contact paths. - Closure path: configuration enters normal operation directly; configured approvals decide concrete ToolCalls. No distinct ultimate-policy feedback loop is established. - Boundary reachability: these configuration and approval surfaces are shipped and reachable, but their organizational function remains setup/action gating rather than S5 identity governance. - Why this is / is not agent-owned: system prompts and approval authority are not S5 by vocabulary or importance. The required identity/ultimate-policy closure is absent. - Evidence: acp/api/v1alpha1/agenttypes.go; acp/internal/controller/toolcall/executor.go; acp/internal/server/server.go. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: external Kubernetes administrators or application owners can act as ultimate authority in a wider organization, but generic platform administration is not automatically parent-owned S5 for ACP standalone.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/e4585aea9287dfa7097bfe057274632bc8ba2cae/assessments/humanlayer-agent-control-plane.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit e4585aea9287dfa7097bfe057274632bc8ba2cae\">e4585ae &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-21T19:01:50+03:00\"><th scope=\"row\"><a href=\"https://github.com/simular-ai/Agent-S\" target=\"_blank\" rel=\"noopener\">Agent S</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-19\">2026-09-19</time></td><td class=\"review-ref\"><a href=\"https://github.com/simular-ai/Agent-S/tree/3aa272d23d2994c7bbde1acbbe0ef8e8d06b8693\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3aa272d23d2994c7bbde1acbbe0ef8e8d06b8693\">3aa272d &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform the requested computer-use transformation by observing the GUI, choosing the next task action, executing it through the first-party action interface, and continuing from returned environment state. - Disturbance / variety regulated: changing screen/application state, task-local uncertainty, action outcomes, tool/UI failures, prior trajectory context and, when enabled, returned local code-execution results. - Decisive decision or feedback right: choose the next substantive GUI/task action from the current instruction, screenshot and trajectory feedback. - Decision owner: the model-driven Agent S3 Worker operating inside the first-party AgentS3 runtime. - Supporting / enforcement mechanisms: AgentS3.predict, Worker history, task-local reflection, grounding/text-coordinate services, action format validation/parsing, pyautogui action generation, CLI screenshot/execute loop, and optional CodeAgent delegation. - Closure path: user task + current screenshot → Worker/model chooses a next action → Agent S converts the action into executable GUI code → CLI executes it against the desktop → changed screen state is captured → the new observation and prior trajectory/reflection enter the next Worker decision. - Boundary reachability: the shipped agents console entrypoint directly constructs AgentS3 and runs this screenshot→prediction→execution loop; no downstream adopter must invent the operational feedback path. - Why this is / is not agent-owned: deterministic parsing/grounding/runtime machinery constrains and executes actions, but the substantive next-action selection is made by the model-driven Worker from current environmental feedback rather than by a fixed script. - Evidence: setup.py; README.md; guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/cliapp.py; guiagents/s3/agents/grounding.py. - Basis: explicit + structural - Confidence: high - Caveats: external model and grounding providers remain execution dependencies, not credited first-party organizational owners. The optional CodeAgent can perform a bounded delegated coding subtask, but that does not change the primary S1 ownership claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct first-party S2 coordination function is established at the current Agent S3 runtime boundary. - Disturbance / variety regulated: no concrete interference, oscillation or conflict among two or more independently acting S1 units is established for the shipped S3 mode. - Decisive decision or feedback right: no S2-specific right to attenuate an evidenced inter-S1 disturbance is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: Worker→CodeAgent task/subtask delegation, task-local reflection, grounding/text helpers and sequential CLI execution were inspected but do not themselves constitute inter-S1 regulation. - Closure path: not applicable; the current runtime closes one primary Worker trajectory and optional subordinate delegation rather than a coordination loop among distinct S1s. - Why this is / is not agent-owned: the S2 function is not established before autonomy classification. AgentS3 explicitly removes hierarchy, and neither a delegated CodeAgent nor a reflection helper provides the required inter-S1 disturbance/attenuation/feedback witness. - Evidence: guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/agents/codeagent.py; guiagents/s3/agents/grounding.py; package entrypoint in setup.py. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established above the one Agent S3 operational trajectory. - Disturbance / variety regulated: current-task execution failures, step limits and CodeAgent budgets are handled within S1/runtime enforcement, not as whole-organization resource/commitment regulation. - Decisive decision or feedback right: no actor is shown holding a whole-system current view plus discretionary authority over multiple S1 commitments, priorities, resources, accountability or intervention. - Decision owner: not established. - Supporting / enforcement mechanisms: the CLI&#39;s finite step loop, Worker trajectory state, CodeAgent budget, pause/quit debugging path and task completion/failure signals provide execution control but not an S3 organizational decision right. - Closure path: not applicable; current state feeds the same Worker S1 or deterministic runtime termination rather than a separate S3 controller that returns portfolio-level decisions. - Why this is / is not agent-owned: no S3 function is established before autonomy classification. An enclosing loop or numeric budget is enforcement, and the current S3 source intentionally lacks the manager hierarchy that might otherwise be investigated for a higher-recursion current-control actor. - Evidence: guiagents/s3/agents/agents.py; guiagents/s3/agents/worker.py; guiagents/s3/cliapp.py; guiagents/s3/agents/codeagent.py. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent complementary audit loop is established in the credited Agent S3 operating mode. - Disturbance / variety regulated: reflection can catch task-local mistakes and bBoN can compare completed rollouts, but neither establishes a qualifying independent audit-and-correction function for the standard live runtime. - Decisive decision or feedback right: no first-party auditor in the credited mode is shown independently validating an ordinary operational claim through a materially separate evidence path and returning a binding/corrective finding into subsequent operation. - Decision owner: not established. - Supporting / enforcement mechanisms: Worker&#39;s reflection agent, ordinary screenshots/action history, stored bBoN rollout result directories, fact captions and comparative judge. - Closure path: reflection advice returns inside the ordinary Worker trajectory; bBoN selects among already-produced rollout directories in an adjacent evaluation path. Neither establishes the required complementary-access audit closure at the declared runtime boundary. - Why this is / is not agent-owned: the function is not established before autonomy classification. Reflection sees the same task instruction, prior Worker action history and current screenshot used by ordinary operation, while bBoN is explicitly outside the ordinary CLI and no live corrective return from its post-hoc selection is evidenced. - Evidence: guiagents/s3/agents/worker.py; guiagents/s3/bbon/comparativejudge.py; README.md; osworldsetup/s3/bbon/ inspected as benchmark/evaluation support. - Basis: explicit + structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no distinct outside-and-then organizational intelligence/adaptation loop is established for Agent S3. - Disturbance / variety regulated: current screenshots and task feedback regulate present execution; they are not a prospective model of the external environment used to adapt future Agent S capability. - Decisive decision or feedback right: no first-party actor is shown generating a future-facing adaptation option from external change and installing/returning that option into current organizational capability. - Decision owner: not established. - Supporting / enforcement mechanisms: static procedural-memory prompts, current task trajectory, reflection, GUI observations, model/grounding configuration and benchmark/evaluation artifacts. - Closure path: not applicable; current-task evidence changes later actions within the same S1 trajectory, while static prompts and benchmark results do not form a shipped prospective adaptation-and-return loop. - Why this is / is not agent-owned: the S4 function is absent. Memory naming, reflection, external-screen perception and benchmark improvement claims do not by themselves establish future/environmental intelligence that changes the harness&#39;s subsequent capability. - Evidence: guiagents/s3/memory/proceduralmemory.py; guiagents/s3/agents/worker.py; README.md; S3 bBoN/evaluation surfaces. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established for the Agent S3 organization. - Disturbance / variety regulated: user task choice, provider/model/grounding configuration, local-env enablement, pause/quit controls and warnings constrain ordinary execution but do not resolve identity-level policy tensions. - Decisive decision or feedback right: no actor is shown receiving an identity/ultimate-policy issue, exercising legitimate ultimate authority over it, and returning an authoritative policy decision that governs subsequent Agent S operation. - Decision owner: not established. - Supporting / enforcement mechanisms: user-supplied task and configuration, CLI flags, safety warning for arbitrary local code execution, runtime pause/quit debugging control and external parent wrappers. - Closure path: not applicable; configuration and operator controls set or interrupt ordinary operation rather than close an identity/ultimate-policy loop. - Why this is / is not agent-owned: the S5 function is not established before autonomy classification. Prompts/configuration, static safety warnings, user invocation and an external OpenClaw parent are constraints or composition surfaces rather than Agent S-owned ultimate-policy authority. - Evidence: README.md; guiagents/s3/cliapp.py; integrations/openclaw/README.md; S3 procedural-memory prompts. - Basis: explicit + structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b6babf55bb8b8628646d733f30c5fd02d69d316b/assessments/agent-s.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b6babf55bb8b8628646d733f30c5fd02d69d316b\">b6babf5 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-27T00:43:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/Reason-Wang/ToolGen\" target=\"_blank\" rel=\"noopener\">ToolGen</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-27\">2026-09-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/Reason-Wang/ToolGen/tree/6839374a255810efe69deea4056eec5c55e25802\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6839374a255810efe69deea4056eec5c55e25802\">6839374 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform the user&#39;s substantive tool-using task through iterative model-selected actions, external tool effects/queries and result-conditioned next-action decisions. - Disturbance / variety regulated: open-ended user requests; very large available tool space; uncertainty about which API/tool fits the current subproblem; action-argument requirements; returned data; invalid/hallucinated action names; external API failures/timeouts/rate limits; incomplete information requiring additional calls. - Decisive decision or feedback right: choose the next task-relevant action/tool and its arguments from the live conversation/observations, interpret returned tool evidence/errors, and decide whether to take another action, answer, or abandon/restart the attempt. - Decision owner: the first-party model-driven ToolGen OpenAgent path. - Supporting / enforcement mechanisms: constrained action-token decoding, tool-token/name conversion, tool documentation lookup, SingleChainAgent state/tree, first-party action dispatch, RapidAPI/StableToolBench transport, observation truncation, status codes and maximum-chain-depth pruning. - Closure path: user task/current conversation -&gt; ToolGen model generates plan/action token/arguments -&gt; SingleChainAgent.takeaction() executes through the tool-state wrapper -&gt; external tool result/status returns -&gt; observation is appended to model context -&gt; later model call changes the next action or terminates -&gt; task progresses toward a final answer. - Boundary reachability: the README&#39;s standard local example directly constructs ToolGen plus RapidAPIWrapper, calls restart() and start(), which reaches the credited SingleChainAgent.dochain() / parse() / takeaction() loop without requiring the repository&#39;s training or evaluation programs. - Why this is / is not agent-owned: deterministic code constrains and executes the available interfaces, while the model selects the task-specific tool/action, generates its arguments and decides what follows from each returned observation. Removing the model decision path while leaving the wrapper/tool metadata in place would not produce materially the same operational choices. - Evidence: README.md; OpenAgent/agents/base.py; OpenAgent/agents/toolgen/toolgen.py; OpenAgent/tools/src/rapidapi/rapidapi.py. - Basis: explicit + structural. - Confidence: high. - Caveats: actual tool effects depend on external ToolBench/StableToolBench/API services. Those dependencies supply environmental capability/execution but do not select the contextual operational action credited to ToolGen.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no qualifying inter-S1 coordination function is established at the one-agent task boundary. - Disturbance / variety regulated: none qualifying; multiple callable tools/APIs create action-choice variety but are not independently accountable first-party operational S1 units whose interaction creates a conflict/oscillation/interference problem. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: action-token constraints, tool lookup/routing, sequential tool calls and shared conversation state are present but do not establish S2. - Closure path: no material inter-S1 disturbance -&gt; coordination decision -&gt; changed affected-S1 behaviour path closes. - Why this is / is not agent-owned: tool selection/routing and sequencing belong to one S1&#39;s task execution; they are not an organizational coordination relation among distinct operations. - Evidence: OpenAgent/agents/base.py; OpenAgent/agents/toolgen/toolgen.py. - Basis: structural absence. - Confidence: high. - Caveats: large tool cardinality does not itself imply a population of S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct superior whole-system current-control function is established above the single ToolGen task operation. - Disturbance / variety regulated: chain depth, status/error conditions and current tool results affect the current run, but these are either deterministic enforcement or ordinary S1 feedback. - Decisive decision or feedback right: no separate actor forms a whole-system current view and exercises discretionary authority over shared resources, commitments, priorities, constraints or multiple operational units. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: maximum step limit, tree/prune state, success/status codes, action constraints and process/runtime bookkeeping. - Closure path: deterministic bounds enforce configured limits while the same S1 model chooses task actions; no superior current-management feedback loop closes. - Why this is / is not agent-owned: SingleChainAgent is an orchestrator in the software sense, but its whole-run controls are pre-authored loop/stopping mechanics. The contextual decisions it carries are the S1 action choices, not a separately evidenced S3 management function. - Evidence: OpenAgent/agents/base.py; OpenAgent/tools/base.py. - Basis: structural absence. - Confidence: high. - Caveats: deterministic enforcement must not be promoted to S3 ownership merely because it controls execution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no qualifying complementary and sufficiently independent audit path is established in the standard OpenAgent runtime. - Disturbance / variety regulated: invalid action names, API/tool errors and external failures are observed and can change later S1 behavior, but they arrive through the ordinary action/observation channel. - Decisive decision or feedback right: no separately situated auditor independently checks operational reality and returns corrective findings into the task loop. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: wrapper status codes, tool observations, invalid-action handling and repository evaluation/pass-rate/preference programs. - Closure path: ordinary tool execution -&gt; ordinary tool observation/status -&gt; same S1 model chooses next action; adjacent evaluation programs produce benchmark measurements rather than corrective runtime audit closure. - Why this is / is not agent-owned: error observation and benchmark evaluation are valuable verification surfaces, but S3 requires complementary independent access and corrective feedback, not normal S1 observations or post-hoc scoring. - Evidence: OpenAgent/agents/base.py; OpenAgent/tools/src/rapidapi/rapidapi.py; README.md. - Basis: explicit + structural absence. - Confidence: high. - Caveats: evaluation infrastructure is adjacent to the runtime boundary and is not wired as an independent corrective auditor for live ToolGen operation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no qualifying external-and-prospective adaptation loop that changes installed/current organizational capability is established in the supported runtime. - Disturbance / variety regulated: the large external tool universe and returned information create current-task choice variety, while training processes can change future model capability offline; neither closes runtime S4 at this boundary. - Decisive decision or feedback right: no runtime actor is shown sensing longer-horizon external conditions, generating a capability/posture adaptation option and adopting it back into current ToolGen capability. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: action-token/tool retrieval, tool documentation, tool virtualization, memorization/retrieval/agent training, downloadable tool metadata and evaluation results. - Closure path: runtime tool retrieval selects a means for the current task; offline training changes checkpoints before deployment. No supported live external sensing -&gt; prospective adaptation option -&gt; changed installed/current capability loop closes. - Why this is / is not agent-owned: selecting among already available tools in response to the current query is S1 action selection. Training/tool memorization/retrieval training are developer/research processes outside the assessed operating mode and do not become S4 merely because they improve future performance. - Evidence: README.md; OpenAgent/agents/toolgen/toolgen.py; repository training/ and evaluation/ boundaries documented in the README. - Basis: explicit + structural absence. - Confidence: high. - Caveats: a future runtime that autonomously changes/persists its tool repertoire or model strategy from environmental evidence would require reassessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy authority is established. - Disturbance / variety regulated: user objective, system prompt, checkpoint, indexing method, configured tool universe, credentials, external service endpoint and chain limit constrain behavior but are supplied by operator/developer/configuration. - Decisive decision or feedback right: define or revise the ultimate purpose/identity/top-level policy governing the ToolGen organization independently of the supplied task/configuration. - Decision owner: external user/developer/configuration; no qualifying runtime S5 owner is established. - Supporting / enforcement mechanisms: static system prompt, model/checkpoint selection, tool-token mapping, API credentials, service URL and maximum-step configuration. - Closure path: no runtime identity/policy issue -&gt; authoritative S5 decision -&gt; changed operational policy loop closes. - Why this is / is not agent-owned: ToolGen decides how to pursue the supplied user task with configured tools, not what ultimate organizational identity/purpose it should adopt. - Evidence: README.md; OpenAgent/agents/toolgen/toolgen.py; OpenAgent/agents/base.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: the static AutoGPT-style system prompt and Finish contract are behavioral constraints, not a runtime S5 authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7d251ac32ca02e836b487a62eb71d305c3315733/assessments/toolgen.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7d251ac32ca02e836b487a62eb71d305c3315733\">7d251ac &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-27T21:38:01+03:00\"><th scope=\"row\"><a href=\"https://github.com/The-Swarm-Corporation/swarms-rs\" target=\"_blank\" rel=\"noopener\">Swarms Rust</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-27\">2026-10-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/The-Swarm-Corporation/swarms-rs/tree/ee1e74cb6e2c94775db88dddb311f2235e3fe9e3\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ee1e74cb6e2c94775db88dddb311f2235e3fe9e3\">ee1e74c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: individually model-directed agent execution of tasks, including tool use, feedback-contingent continuation and optional peer-agent delegation. - Disturbance / variety regulated: unknown task subtasks, model/tool errors, new tool outputs, incomplete task-evaluator feedback and provider failures. - Decisive decision or feedback right: choose tool/agent operations and subsequent task steps from model replies; continue, hand off or finish as new results arrive. - Decision owner: the invoked SwarmsAgent model-backed loop within one operational agent, using externally supplied LLM completion but first-party loop and tools. - Supporting / enforcement mechanisms: SwarmsAgentBuilder, tool registration, chat, Agent::run, taskevaluator, retry and max-loop settings, SubAgentTool and HandoffTool. - Closure path: user task → model completion and tool/delegation choice → executed tool/child result → saved conversation and new agent prompt → next action or completion. - Boundary reachability: README shows actual builder/use of SwarmsAgent through the published crate; Agent::run calls the loop, while opt-in first-party builder methods register handoff/subagent tools in the model-visible tool set. - Why this is / is not agent-owned: model choice determines which operation is taken in response to the task, while fixed retry counters and memory only bound it. - Evidence: run loop, delegation implementation, README quickstart. - Basis: structural and documented. - Confidence: high on static source architecture. - Caveats: agent action success and reasoning quality require a live configured provider; this review executed no paid/model-dependent task.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: bounded attenuation of concurrent operating-unit interference when multiple independently executing Rust agents feed a common graph join or two invocations contend over the same concurrent-workflow task key. - Distinct S1 units: separately invoked Agent workers in a configured DAGWorkflow graph, or two concurrently initiated operations of the same ConcurrentWorkflow instance. - Inter-S1 disturbance: independent predecessor branches resolve concurrently and might start the same downstream worker more than once; duplicate active task runs might overwrite or intermingle their task-specific shared conversation. - Attenuating coordination relation: graph incoming-edge resolution waits for all predecessor decisions, aggregates accepted outputs, and atomically claims each target using DashSet::insert; concurrent workflow&#39;s task-level DashSet denies duplicate in-flight same-key runs, released when the run exits. - Feedback into subsequent S1 behaviour: a downstream agent only receives resolved, accepted upstream inputs and starts once, or does not run when all edges are skipped; a duplicate workflow invocation is rejected before it launches an interfering set of agents. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the claim rests narrowly on actual collision-prevention and concurrent fan-in resolution, not on the mere presence of graph edges, router names, parallel execution or conversation history. - Disturbance / variety regulated: simultaneous predecessor completions, skipped/error predecessor branches, fan-in duplicate launch races and same-task concurrent invocation. - Decisive decision or feedback right: enforce a single downstream start after incoming-branch resolution and reject a second active run of the same task key. - Decision owner: deterministic first-party graph/workflow concurrency gates, hence C rather than an autonomous S2 model owner. - Supporting / enforcement mechanisms: DAGWorkflow::executeworkflow, executenodetracked, propagate, edgetracker, started; ConcurrentWorkflow::run and RunningTask guard. - Closure path: parallel operating outputs or contending invocation → first-party graph/task key gate → joined accepted input, skipped downstream work or explicit duplicate error → bounded later agent execution. - Boundary reachability: executeworkflow calls executenodetracked and propagate on the published first-party graph type; ConcurrentWorkflow::run enforces the task gate on the documented direct run method. - Why this is / is not agent-owned: collision and launch grants are fixed Rust concurrency decisions, not model-authored coordination rules. - Evidence: graph join and atomic claim, duplicate-task guard. - Basis: structural. - Confidence: medium-high for these narrow modes. - Caveats: no global scheduling or shared-resource arbitration across unrelated swarm instances; graph joins and task guards do not prove resource-level coordination for arbitrary side effects.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no independently evidenced controller regulating the present whole-swarm operating commitments based on a comprehensive status view. - Disturbance / variety regulated: uneven worker progress, partial failures and changing priority could require adaptive whole-team direction, but the inspected shipped topology instead follows configured steps and predetermined graph edges. - Decisive decision or feedback right: SwarmRouter selects a preconfigured variant at construction; graph branches are configured functions; local LLM delegation only chooses a child&#39;s task within one operating agent. - Decision owner: application author and deterministic workflow/router for whole-application topology; individual model agents own their own S1 actions. - Supporting / enforcement mechanisms: router enum dispatch, graph edge functions, rearrange text flow, concurrent and sequential workflow loops, task-evaluator inside the individual agent. - Closure path: returned agent results can feed another preconfigured step, but no evidence that a model or other distinct function sees the whole current swarm and revises global allocations/controls on result feedback. - Whole-system current view: graph execution results and shared conversation are accumulated by orchestration code; no separate whole-swarm supervisory interpretation/choice found. - Current-control decision scope: graph/router/rearrange schedule is operator-defined, while handoff is agent-local; neither was elevated to whole-system governance. - Boundary reachability: published workflow API is reachable; its reachable paths are deterministic dispatch/conditions, not a full S3 controller. - Why this is / is not agent-owned: model-selected addhandoff transfers one task, and model tool choices remain operating-level; they do not prove a distinct supervisor regulating all worker commitments. - Evidence: router dispatch, flow execution, DAG execution, handoff. - Basis: structural bounded absence. - Confidence: medium. - Caveats: downstream users can author their own supervisor using this general-purpose library; an unobserved custom application is not part of the shipped assessed system.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independent complementary sampling of operational truth against ordinary producer reporting established for the installed Rust swarm. - Disturbance / variety regulated: potentially false or incomplete agent output and hidden failures. - Decisive decision or feedback right: task evaluator and downstream agents may reconsider production output, but the evaluator receives same agent-local context and is part of the normal work loop. - Decision owner: producing operating agent and ordinary application workflow; no distinct audit owner is evidenced. - Supporting / enforcement mechanisms: local taskevaluator tool, graph error/timeout reporting, per-agent logs, result persistence and general tests. - Closure path: evaluator feedback can prompt another loop of the producing agent; an independent observation/audit finding with a separate corrective authority is not shown. - Why this is / is not agent-owned: a model reporting its own task completion or downstream summarization is ordinary operating QA, not independent complementary S3 inspection. - Evidence: task-evaluator implementation, graph result/error handling. - Basis: structural bounded absence. - Confidence: medium. - Caveats: an external observer could audit application effects, but none is installed as a first-party alternative access channel here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no shipped function prospectively sensing external change and steering future capabilities of the Rust swarm itself. - Disturbance / variety regulated: changing model availability, new task domains, tool ecosystems and operational threats might require strategic changes. - Decisive decision or feedback right: model/tool/provider, flow configuration and future crate upgrades are chosen by an external application author or developer, not by an in-scope S4 agent. - Decision owner: users/developers of host applications and package maintainers outside this runtime. - Supporting / enforcement mechanisms: extensible model/tool interfaces, optional external MCP servers, configurable prompts and runtime state. - Closure path: model tools may answer a user&#39;s research question as an operating task; no environmental scan → durable future-system option → current-control implementation loop for the swarm is established. - Why this is / is not agent-owned: general ability to ask an LLM for plans or research does not assign it ongoing prospective adaptation authority over this runtime. - Evidence: agent builder and model/tool interfaces, runtime router configuration. - Basis: structural bounded absence. - Confidence: medium. - Caveats: application-specific model research or strategy could be built by adopters; no such in-boundary policy feed was demonstrated.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no established ultimate identity/policy-setting authority inside one runtime swarm as distinguished from ordinary developer configuration. - Disturbance / variety regulated: conflicts over ultimate purposes or legitimate authority for changing swarm identity would require policy adjudication. - Decisive decision or feedback right: builder-provided instructions/rules define ordinary task constraints, but no in-runtime purpose dispute is routed to a recognized policy owner and returned as governing charter. - Decision owner: application author/configurator or package maintainers outside the assessed operating instance. - Supporting / enforcement mechanisms: systemprompt, builder settings, flow rules, agent handoff and stop conditions. - Closure path: configuration is read and enforced during tasks; no identity-level challenge → legitimate policy judgment → binding change to subsequent operation is documented. - Why this is / is not agent-owned: static initial rules and human ownership of source code are not automatic evidence of S5 ownership in this recursion. - Evidence: builder/prompt and handoff configuration, rearrange rules. - Basis: structural bounded absence. - Confidence: medium. - Caveats: organizational policies governing the vendor or adopter are different recursion levels and are not imported.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/1748287ed7669687ba3ea26b5bcde6ccf2978417/assessments/sw/swarms-rust.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 1748287ed7669687ba3ea26b5bcde6ccf2978417\">1748287 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T17:01:12+03:00\"><th scope=\"row\"><a href=\"https://github.com/i-am-bee/beeai-framework\" target=\"_blank\" rel=\"noopener\">BeeAI Framework</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/i-am-bee/beeai-framework/tree/6a8b28f54073790f9a8135320a0e9ed1d4cef602\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6a8b28f54073790f9a8135320a0e9ed1d4cef602\">6a8b28f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: agents independently reason and use tools toward outcomes.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: first-party handoff/workflow mechanisms decompose or route work rather than provide mutual adjustment/collision regulation among autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the main agent chooses specialists during its own task but no whole-system current commitment/resource regulator is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: observability, middleware and requirement checking do not instantiate a distinct independent audit channel with corrective authority.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, RAG and environment tools serve current-task reasoning rather than a prospective intelligence loop coupled back to S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: RequirementAgent rules, tools, prompts and workflow policy are configured constraints, not autonomous ultimate-policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d3c36ab7c17230290253c004628399e193b7f685/assessments/beeai-framework.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d3c36ab7c17230290253c004628399e193b7f685\">d3c36ab &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"2\" data-assessment-at=\"2026-09-17T00:25:41+03:00\"><th scope=\"row\"><a href=\"https://github.com/mastra-ai/mastra\" target=\"_blank\" rel=\"noopener\">Mastra</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/mastra-ai/mastra/tree/76cec9be889c0a6ae7f51fbf25356d5a06019351\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 76cec9be889c0a6ae7f51fbf25356d5a06019351\">76cec9b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: agents autonomously choose tools and iterate toward task completion.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: supervisor routing chooses/delegates work but no distinct mutual-adjustment or conflict-dampening relation among autonomous S1s is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: the first-party supervisor/network path owns current selection and sequencing of subagents/workflows/tools using task history and completion state. That is composable current regulation, but not the default closed path for all agents.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: first-party task-completion scorers separately assess whether the supervisor&#39;s current result satisfies completion criteria; a failed verdict blocks completion, adds feedback and causes further iteration. The audit decision right is composable/configured rather than universally enabled.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, RAG and planning remain current-task capabilities; no distinct prospective environment-to-S3 loop is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: instructions, primitive descriptions, scorers, approvals and workflow/network policy remain developer/user supplied.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/55752d6939d7900cd6f4b25f6009dd933581e885/assessments/mastra.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 55752d6939d7900cd6f4b25f6009dd933581e885\">55752d6 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-28T16:23:04+03:00\"><th scope=\"row\"><a href=\"https://github.com/2FastLabs/agent-squad\" target=\"_blank\" rel=\"noopener\">Agent Squad</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/2FastLabs/agent-squad/tree/31eccfeb0d546262d1d0ec2e2e5239186f8d2954\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 31eccfeb0d546262d1d0ec2e2e5239186f8d2954\">31eccfe &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform user-facing specialist work by interpreting a routed/delegated request and producing an outcome through the selected agent&#39;s model/tool-backed operating loop. - Disturbance / variety regulated: heterogeneous user intents, task-specific context, conversation history, provider/tool responses, and task-domain uncertainty encountered by each registered specialist. - Decisive decision or feedback right: decide how to process the assigned request and what response/tool-mediated result to produce within the concrete agent implementation. - Decision owner: the selected model-driven Agent implementation; in supervisor mode each contacted specialist owns its delegated operational response. - Supporting / enforcement mechanisms: classifier selection, AgentSquad.dispatchtoagent, session/chat storage, provider adapters, tool configuration, streaming wrappers and metadata/logging. - Closure path: user request → classifier or supervisor selects/delegates to an agent → agent processrequest interprets and executes the task → result is returned and persisted into conversation state → later requests can use that state. - Boundary reachability: the standard AgentSquad runtime directly invokes registered agents through processrequest; SupervisorAgent likewise invokes team agents directly. No adjacent repository-development actor is required to expose this operating discretion. - Why this is / is not agent-owned: the runtime transports and records the request/result, while the model-driven selected agent owns the substantive response/tool-use decision within its configured role. - Evidence: orchestrator.py; agents/agent.py; concrete shipped agent implementations; agents/supervisoragent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: external model providers execute model inference and application developers configure the available agents/tools; those dependencies do not remove the first-party runtime&#39;s shipped autonomous operating path.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party operating path establishes disturbance-specific attenuation of interference, conflict or oscillation among distinct S1 units at this recursion. - Disturbance / variety regulated: no qualifying inter-S1 disturbance is established. Supervisor specialists being mutually unaware is a communication topology, not evidence of destructive interference; lexical role overlap is only a diagnostic similarity signal. - Decisive decision or feedback right: no S2-specific decision/feedback right is established. - Decision owner: not established for S2. - Supporting / enforcement mechanisms: SupervisorAgent.sendmessages, sole-intermediary context forwarding, parallel fan-out, per-agent histories, ordinary classifier routing, and the separate AgentOverlapAnalyzer diagnostic. - Closure path: ordinary messages can influence later specialist responses, but the repository does not establish a disturbance-specific coordination result that is selected in response to concrete inter-S1 interference and then returned to change subsequent S1 behaviour. - Why this is / is not agent-owned: the supervisor autonomously decides whom to contact for a user task, but delegation and information mediation do not become S2 without the required inter-S1 disturbance/attenuation relation. The overlap analyzer does not close the gap because its conflict labels are not wired into the operating runtime. - Evidence: agents/supervisoragent.py; orchestrator.py; agentoverlapanalyzer.py; repository search for analyzeoverlap() consumers. - Basis: current-contract same-ref correction. - Confidence: high. - Caveats: a downstream application could compose Supervisor messages or overlap diagnostics into a real conflict-resolution loop, but that would be a separate system-in-focus unless such closure becomes first-party and reachable in the reviewed distribution. - Distinct S1 units: multiple registered specialist agents can be contacted in supervisor mode. - Inter-S1 disturbance: not established as an actual or structurally evidenced operational interference/conflict/oscillation. - Attenuating coordination relation: no relation is tied to a qualifying disturbance; sole-intermediary messaging is generic communication/delegation at this boundary. - Feedback into subsequent S1 behaviour: agent history and forwarded context affect later replies, but not as demonstrated feedback from an S2-specific disturbance attenuation decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: it is not; the accepted evidence supports generic routing, delegation and mediation only.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct first-party whole-system current-control function is established over a portfolio of S1 resources, commitments, priorities or constraints. - Disturbance / variety regulated: not established as S3 at this recursion. - Decisive decision or feedback right: not established for whole-system current regulation. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: classifier selection, supervisor choice of which specialists to contact, parallel fan-out, request aggregation, execution timing/logging and application configuration. - Closure path: not applicable as S3. - Why this is / is not agent-owned: the supervisor manages one user-request composition and the classifier chooses an agent, but neither inspected path establishes a whole-current-system view plus authority to bargain/reallocate resources, commitments, priorities or constraints across operations on behalf of the organization as a whole. - Evidence: orchestrator.py; agents/supervisoragent.py. - Basis: structural absence review. - Confidence: high. - Caveats: supervisor naming and task delegation are not S3 shortcuts.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no materially independent complementary audit path is established that challenges ordinary operational claims and returns findings into corrective control. - Disturbance / variety regulated: not established as S3. - Decisive decision or feedback right: not established for independent audit judgment. - Decision owner: not established for S3. - Supporting / enforcement mechanisms: ordinary tests, tracing/logging, response aggregation and role-overlap diagnostics are available adjacent/supporting surfaces, not a complementary operational audit loop. - Closure path: not applicable as S3. - Why this is / is not agent-owned: the inspected operating paths do not separate an auditor with materially different access from the ordinary production agents and return its findings into correction/re-verification. - Evidence: shipped agent/runtime surfaces; agentoverlapanalyzer.py; tests/examples excluded from operating ownership. - Basis: structural absence review. - Confidence: high. - Caveats: a downstream application can register a reviewer-like agent, but generic extensibility does not establish first-party S3 ownership.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective intelligence loop develops adaptation options for the Agent Squad organization and returns them into present capability. - Disturbance / variety regulated: not established as S4. - Decisive decision or feedback right: not established for future-oriented organizational adaptation. - Decision owner: not established for S4. - Supporting / enforcement mechanisms: conversation history, classifiers, retrievers, provider/tool calls and application configuration can introduce external information but remain task-operation mechanisms. - Closure path: not applicable as S4. - Why this is / is not agent-owned: retrieval and ongoing conversation can react to external content, but the repository does not establish a prospective environment model → adaptation option → present capability change loop for Agent Squad itself. - Evidence: runtime/classifier/storage/agent surfaces at the accepted revision. - Basis: structural absence review. - Confidence: high. - Caveats: downstream applications may implement research or self-improvement agents, but their organizational adaptation cannot be inherited by the generic framework.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy closure is established at the Agent Squad organization recursion. - Disturbance / variety regulated: not established as an S5 identity/policy issue. - Decisive decision or feedback right: agent membership, role descriptions, system prompts, provider/tool configuration and supervisory rules are supplied by application/developer configuration rather than decided through a shipped S5 loop. - Decision owner: application developer/operator outside the autonomous assessed runtime for these choices. - Supporting / enforcement mechanisms: prompts, AgentOptions, team lists, classifier configuration and supervisor guidelines constrain operation. - Closure path: configuration is loaded into subsequent operation, but no identity/ultimate-policy issue is raised, adjudicated by legitimate S5 authority inside the assessed system, and returned as a runtime policy decision. - Why this is / is not agent-owned: the supervisor follows the configured role/team/prompt contract; it does not own ultimate authority to redefine Agent Squad&#39;s organizational identity or policy at this recursion. - Evidence: agents/agent.py; orchestrator.py; agents/supervisoragent.py. - Basis: structural absence review. - Confidence: high. - Caveats: parent developers/operators plainly configure the library, but ordinary construction/configuration is not published as P without a complete identity/policy decision loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/059a7330392bb1cb7fcabfe9d0b651c614e51676/assessments/agent-squad.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 059a7330392bb1cb7fcabfe9d0b651c614e51676\">059a733 &#8599;</a></td></tr>"];
